  "id": "physiologie-3",
  "fach": "Physiologie",
  "title": "Erregungsphysiologie: Aktionspotenzial, Synapse",
  "kern": [
   {
    "de": "Ein Aktionspotenzial ist ein sehr kurzer, kontrollierter Ionen-Stromstoß an der Membran von Nerven- oder Muskelzellen – das Startsignal, keine Kontraktion.",
    "tr": "Aksiyon potansiyeli sinir/kas hücresi zarında çok kısa, kontrollü bir iyon akımıdır; kasılmanın kendisi değil, başlama sinyalidir."
   },
   {
    "de": "Nur wenn ein Reiz den Schwellenwert (ca. −50 bis −55 mV) erreicht, startet ein Aktionspotenzial.",
    "tr": "Ancak uyarı eşik değere (yaklaşık −50/−55 mV) ulaşırsa aksiyon potansiyeli başlar."
   },
   {
    "de": "Bei der Depolarisation öffnen spannungsabhängige Na⁺-Kanäle, Na⁺ strömt ein und die Membran wird bis ca. +30 mV positiv.",
    "tr": "Depolarizasyonda voltaja bağlı Na⁺ kanalları açılır, Na⁺ içeri akar, zar yaklaşık +30 mV'a kadar pozitifleşir."
   },
   {
    "de": "Bei der Repolarisation sind die Na⁺-Kanäle inaktiviert, K⁺-Kanäle öffnen und K⁺ strömt aus der Zelle.",
    "tr": "Repolarizasyonda Na⁺ kanalları inaktive olur, K⁺ kanalları açılır ve K⁺ dışarı çıkar."
   },
   {
    "de": "Bei der Hyperpolarisation ist das Potenzial negativer als das Ruhepotenzial (bis −90 mV), die Zelle ist schwerer erregbar.",
    "tr": "Hiperpolarizasyonda potansiyel dinlenme değerinden daha negatiftir (−90 mV'a kadar); hücre daha zor uyarılır."
   },
   {
    "de": "Nach dem Alles-oder-Nichts-Prinzip ist ein Aktionspotenzial immer gleich groß oder findet gar nicht statt.",
    "tr": "Hep ya hiç ilkesi: aksiyon potansiyeli ya tam boyutta oluşur ya hiç oluşmaz."
   },
   {
    "de": "Mehr Kraft entsteht durch mehr Aktionspotenziale (höhere Frequenz) oder mehr beteiligte Muskelfasern, nicht durch stärkere APs.",
    "tr": "Daha fazla kuvvet, daha güçlü AP ile değil, daha sık AP veya daha çok kas lifinin katılmasıyla oluşur."
   },
   {
    "de": "In der absoluten Refraktärzeit ist kein neues AP möglich, in der relativen nur mit stärkerem Reiz.",
    "tr": "Mutlak refrakter sürede yeni AP mümkün değildir; göreceli refrakter sürede yalnızca daha güçlü uyarıyla mümkündür."
   },
   {
    "de": "Die Refraktärzeit schützt vor Dauererregung, begrenzt die maximale Reizfrequenz und sorgt für Weiterleitung in eine Richtung.",
    "tr": "Refrakter süre sürekli uyarılmayı önler, maksimum uyarı frekansını sınırlar ve iletimin tek yönlü olmasını sağlar."
   },
   {
    "de": "Bei kontinuierlicher Erregungsleitung (ohne Myelin) wird das AP Abschnitt für Abschnitt neu ausgelöst, bei saltatorischer springt es von Ranvier-Schnürring zu Schnürring.",
    "tr": "Miyelinsiz sinirde AP parça parça yeniden oluşur (kesintisiz iletim); miyelinli sinirde Ranvier boğumundan boğumuna sıçrar (saltatorik iletim)."
   },
   {
    "de": "Die Leitungsgeschwindigkeit hängt von Myelinisierung, Axondurchmesser und Temperatur ab.",
    "tr": "İletim hızı miyelinizasyon, akson çapı (kalın = hızlı) ve sıcaklığa (soğuk = yavaş) bağlıdır."
   },
   {
    "de": "An der chemischen Synapse löst Ca²⁺-Einstrom die Freisetzung von Neurotransmittern aus, die an Rezeptoren der Postsynapse binden.",
    "tr": "Kimyasal sinapsta Ca²⁺ girişi nörotransmitter salınımını tetikler; bunlar postsinaptik reseptörlere bağlanır."
   }
  ],
